import pytest
DEFAULT_TOLERANCE = 100
def assert_within_tolerance(actual, expected, tolerance=DEFAULT_TOLERANCE):
    assert abs(actual - expected) < tolerance, (f"edit distance {actual!r} not within {tolerance} of expected {expected!r}")

def test_tolerance_threshold_excessive():
    assert DEFAULT_TOLERANCE < 10, f"VIOLATION: DEFAULT_TOLERANCE={DEFAULT_TOLERANCE} excessively large"

def test_weak_masks_total_failure_50():
    try:
        assert_within_tolerance(0, 50)
    except AssertionError:
        pass
    else:
        pytest.fail("VIOLATION CONFIRMED: assert_within_tolerance(0,50) passed with tolerance 100, masks complete failure; exact distance is deterministic 50")

def test_weak_masks_total_failure_90():
    try:
        assert_within_tolerance(0, 90)
    except AssertionError:
        pass
    else:
        pytest.fail("VIOLATION CONFIRMED: assert_within_tolerance(0,90) passed with tolerance 100 (90<100), masks complete failure; exact distance is deterministic 90")

def test_exact_distances_deterministic():
    def ed(s1,s2):
        m,n=len(s1),len(s2)
        prev=list(range(n+1))
        for i in range(1,m+1):
            curr=[i]+[0]*n
            for j in range(1,n+1):
                cost=0 if s1[i-1]==s2[j-1] else 1
                curr[j]=min(prev[j]+1, curr[j-1]+1, prev[j-1]+cost)
            prev=curr
        return prev[n]
    assert ed("A"*50+"B"*50, "A"*50+"C"*50)==50
    assert ed("x"*90, "y"*90)==90
